import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as c,c as d,d as i}from"./app-2d48fecb.js";const o={},t=i('<h1 id="在编辑器更新后迁移游戏文件" tabindex="-1"><a class="header-anchor" href="#在编辑器更新后迁移游戏文件" aria-hidden="true">#</a> 在编辑器更新后迁移游戏文件</h1><p>WebGAL Terre 4.6 大幅调整了用户数据组织方式。本文保留 4.5 及更早版本的手动迁移说明，并额外说明从 4.5 升级到 4.6 时应如何迁移。</p><h2 id="从-4-5-升级到-4-6" tabindex="-1"><a class="header-anchor" href="#从-4-5-升级到-4-6" aria-hidden="true">#</a> 从 4.5 升级到 4.6</h2><p>从 4.6 开始，WebGAL Terre 会把游戏、模板、定制引擎和导出内容统一管理在用户数据目录中。4.6 的安装目录下不再默认提供旧版本使用的 <code>public/games</code>、<code>public/templates</code>、<code>assets/templates/Derivative_Engine</code> 等用户工程目录，因此把 4.5 的文件复制到 4.6 安装目录下的同名目录不再可行。</p><p>请按以下方式手动迁移：</p><ol><li>先打开一次 WebGAL Terre 4.6，让 Terre 创建新的用户数据目录。</li><li>在 WebGAL Terre 4.6 中打开设置，进入用户数据相关设置，点击打开用户数据目录。</li><li>打开旧版 WebGAL Terre 4.5 的安装目录。</li><li>将 4.5 中 <code>public/games</code> 目录下的每个游戏工程文件夹复制到 4.6 用户数据目录的 <code>games</code> 目录下。</li><li>如果你有自定义模板，将 4.5 中 <code>public/templates</code> 下的自定义模板文件夹复制到 4.6 用户数据目录的 <code>templates</code> 目录下。内置模板不需要复制。</li><li>如果你导入过定制引擎，将 4.5 中 <code>assets/templates/Derivative_Engine</code> 下的定制引擎文件夹复制到 4.6 用户数据目录的 <code>derivative-engines</code> 目录下。</li><li>回到 WebGAL Terre 4.6，刷新游戏列表、模板列表或重启 Terre，确认内容是否已经出现。</li></ol><p>4.6 用户数据目录中主要目录的作用如下：</p><ul><li><code>games</code>：保存你的游戏工程。旧版 <code>public/games/&lt;游戏名&gt;</code> 应迁移为 <code>games/&lt;游戏名&gt;</code>。</li><li><code>templates</code>：保存你创建或导入的自定义模板。旧版 <code>public/templates/&lt;模板名&gt;</code> 应迁移为 <code>templates/&lt;模板名&gt;</code>。</li><li><code>derivative-engines</code>：保存定制引擎。旧版 <code>assets/templates/Derivative_Engine/&lt;引擎名&gt;</code> 应迁移为 <code>derivative-engines/&lt;引擎名&gt;</code>。</li><li><code>Exported_Games</code>：保存从 Terre 导出的游戏文件。</li><li><code>config.json</code>：保存 Terre 的用户数据配置，请不要在不了解含义的情况下手动修改。</li></ul><p>如果你使用 portable 模式，实际用户数据目录是安装目录下的 <code>data</code> 文件夹；迁移时仍然把游戏、模板和定制引擎放入该目录下的 <code>games</code>、<code>templates</code>、<code>derivative-engines</code>。</p><p>自 4.6 开始，后续升级 WebGAL Terre 时不再需要手动迁移游戏文件。用户数据目录会在版本升级后继续复用，除非你主动更改用户数据目录或使用 portable 模式切换了数据位置。</p><h2 id="_4-5-及更早版本之间的迁移游戏" tabindex="-1"><a class="header-anchor" href="#_4-5-及更早版本之间的迁移游戏" aria-hidden="true">#</a> 4.5 及更早版本之间的迁移游戏</h2><p>以下说明仅适用于 4.5 及更早版本之间的迁移。如果你要升级到 4.6 或更新版本，请使用上文的用户数据目录迁移方式。</p><p>WebGAL Terre 编辑器的游戏工程文件目录在 <code>public/games</code> 目录下。在这个目录下，你可以看到你所创建的游戏名称。</p><p>当你下载或安装了新的编辑器后，你可以将旧版本编辑器下的游戏直接迁移到新版本编辑器的相同目录下，然后打开新版本编辑器，即可使用。</p><p>除大版本（版本号的第一位数字）升级的兼容性不保证之外，一般来说游戏都可以向下兼容。</p><h2 id="_4-5-及更早版本之间的迁移模板和定制引擎" tabindex="-1"><a class="header-anchor" href="#_4-5-及更早版本之间的迁移模板和定制引擎" aria-hidden="true">#</a> 4.5 及更早版本之间的迁移模板和定制引擎</h2><p>如果你创建了模板，或导入了定制引擎，你也需要迁移这些文件到新版本的编辑器。模板文件在 <code>public/templates</code> 目录下。<br> 定制引擎在 <code>assets/templates/Derivative_Engine</code> 目录下。你需要将这些文件迁移到新版本的相同目录下。</p>',17),a=[t];function r(l,s){return c(),d("div",null,a)}const m=e(o,[["render",r],["__file","migration.html.vue"]]);export{m as default};
